import java.util.*;

public class Node {
    public int data;
    public Node next;
    public Node(int val) {
        data = val;
        next = null;
    }
}

public class GfG {
    public static Node divide(Node head) {
        // Result list to hold even nodes
        Node resStart = null;
        Node resEnd = null;
        // Pointers for the original list
        Node curr = head;
        Node prev = null;
        // Move all even nodes from original
        // to result
        while (curr != null) {
            // If current node is even
            if (curr.data % 2 == 0) {
                // Remove the current even node
                // from the original list
                if (prev != null) {
                    prev.next = curr.next;
                } else {
                    // If the even node is at the head
                    head = curr.next;
                }
                // Add the current even node to the result list
                if (resStart == null) {
                    resStart = curr;
                    resEnd = resStart;
                } else {
                    resEnd.next = curr;
                    resEnd = resEnd.next;
                }
                curr = curr.next;
            }
            // If the node is odd, just move to the next
            else {
                prev = curr;
                curr = curr.next;
            }
        }
        // If there are no even nodes, return
        // the original list
        if (resStart == null)
            return head;
        // Append the remaining original list
        // (odd nodes) to the result list
        resEnd.next = head;
        // Return the result list (starting with even nodes)
        return resStart;
    }

    public static void main(String[] args) {
        // Creating linked list: 17->15->8->9->2->4->6
        Node head = new Node(17);
        head.next = new Node(15);
        head.next.next = new Node(8);
        head.next.next.next = new Node(9);
        head.next.next.next.next = new Node(2);
        head.next.next.next.next.next = new Node(4);
        head.next.next.next.next.next.next = new Node(6);
        head = divide(head);
        Node curr = head;
        while (curr != null) {
            System.out.print(curr.data);
            if (curr.next != null)
                System.out.print("->");
            curr = curr.next;
        }
    }
}
